fb // - ATLAS_13TeV_2OSLEP_chargino_inclusive_139invfb class Analysis_ATLAS_13TeV_2OSLEP_chargino_139invfb : public Analysis { protected: Cutflow _cutflow; public: // Required detector sim static constexpr const char* detector = &quot;ATLAS&quot;; Analysis_ATLAS_13TeV_2OSLEP_chargino_139invfb(): _cutflow(&quot;ATLAS 2-lep chargino-W 13 TeV&quot;, {&quot;Two_OS_leptons&quot;, &quot;mll_25&quot;, &quot;b_jet_veto&quot;, &quot;MET_110&quot;, &quot;MET_significance_10&quot;, &quot;n_j&lt;=1&quot;, &quot;m_ll_m_Z&quot;}) { // Counters for the number of accepted events for each signal region // Inclusive SRs _counters[&quot;SR-DF-0J-100_inclusive&quot;] = EventCounter(&quot;SR-DF-0J-100_inclusive&quot;); _counters[&quot;SR-DF-0J-160_inclusive&quot;] = EventCounter(&quot;SR-DF-0J-160_inclusive&quot;); _counters[&quot;SR-DF-0J-100-120_inclusive&quot;] = EventCounter(&quot;SR-DF-0J-100-120_inclusive&quot;); _counters[&quot;SR-DF-0J-120-160_inclusive&quot;] = EventCounter(&quot;SR-DF-0J-120-160_inclusive&quot;); _counters[&quot;SR-DF-1J-100_inclusive&quot;] = EventCounter(&quot;SR-DF-1J-100_inclusive&quot;); _counters[&quot;SR-DF-1J-160_inclusive&quot;] = EventCounter(&quot;SR-DF-1J-160_inclusive&quot;); _counters[&quot;SR-DF-1J-100-120_inclusive&quot;] = EventCounter(&quot;SR-DF-1J-100-120_inclusive&quot;); _counters[&quot;SR-DF-1J-120-160_inclusive&quot;] = EventCounter(&quot;SR-DF-1J-120-160_inclusive&quot;); _counters[&quot;SR-SF-0J-100_inclusive&quot;] = EventCounter(&quot;SR-SF-0J-100_inclusive&quot;); _counters[&quot;SR-SF-0J-160_inclusive&quot;] = EventCounter(&quot;SR-SF-0J-160_inclusive&quot;); _counters[&quot;SR-SF-0J-100-120_inclusive&quot;] = EventCounter(&quot;SR-SF-0J-100-120_inclusive&quot;); _counters[&quot;SR-SF-0J-120-160_inclusive&quot;] = EventCounter(&quot;SR-SF-0J-120-160_inclusive&quot;); _counters[&quot;SR-SF-1J-100_inclusive&quot;] = EventCounter(&quot;SR-SF-1J-100_inclusive&quot;); _counters[&quot;SR-SF-1J-160_inclusive&quot;] = EventCounter(&quot;SR-SF-1J-160_inclusive&quot;); _counters[&quot;SR-SF-1J-100-120_inclusive&quot;] = EventCounter(&quot;SR-SF-1J-100-120_inclusive&quot;); _counters[&quot;SR-SF-1J-120-160_inclusive&quot;] = EventCounter(&quot;SR-SF-1J-120-160_inclusive&quot;); // Binned SRs _counters[&quot;SR-DF-0J-100-105&quot;] = EventCounter(&quot;SR-DF-0J-100-105&quot;); _counters[&quot;SR-DF-0J-105-110&quot;] = EventCounter(&quot;SR-DF-0J-105-110&quot;); _counters[&quot;SR-DF-0J-110-120&quot;] = EventCounter(&quot;SR-DF-0J-110-120&quot;); _counters[&quot;SR-DF-0J-120-140&quot;] = EventCounter(&quot;SR-DF-0J-120-140&quot;); _counters[&quot;SR-DF-0J-140-160&quot;] = EventCounter(&quot;SR-DF-0J-140-160&quot;); _counters[&quot;SR-DF-0J-160-180&quot;] = EventCounter(&quot;SR-DF-0J-160-180&quot;); _counters[&quot;SR-DF-0J-180-220&quot;] = EventCounter(&quot;SR-DF-0J-180-220&quot;); _counters[&quot;SR-DF-0J-220-260&quot;] = EventCounter(&quot;SR-DF-0J-220-260&quot;); _counters[&quot;SR-DF-0J-260&quot;] = EventCounter(&quot;SR-DF-0J-260&quot;); _counters[&quot;SR-DF-1J-100-105&quot;] = EventCounter(&quot;SR-DF-1J-100-105&quot;); _counters[&quot;SR-DF-1J-105-110&quot;] = EventCounter(&quot;SR-DF-1J-105-110&quot;); _counters[&quot;SR-DF-1J-110-120&quot;] = EventCounter(&quot;SR-DF-1J-110-120&quot;); _counters[&quot;SR-DF-1J-120-140&quot;] = EventCounter(&quot;SR-DF-1J-120-140&quot;); _counters[&quot;SR-DF-1J-140-160&quot;] = EventCounter(&quot;SR-DF-1J-140-160&quot;); _counters[&quot;SR-DF-1J-160-180&quot;] = EventCounter(&quot;SR-DF-1J-160-180&quot;); _counters[&quot;SR-DF-1J-180-220&quot;] = EventCounter(&quot;SR-DF-1J-180-220&quot;); _counters[&quot;SR-DF-1J-220-260&quot;] = EventCounter(&quot;SR-DF-1J-220-260&quot;); _counters[&quot;SR-DF-1J-260&quot;] = EventCounter(&quot;SR-DF-1J-260&quot;); _counters[&quot;SR-SF-0J-100-105&quot;] = EventCounter(&quot;SR-SF-0J-100-105&quot;); _counters[&quot;SR-SF-0J-105-110&quot;] = EventCounter(&quot;SR-SF-0J-105-110&quot;); _counters[&quot;SR-SF-0J-110-120&quot;] = EventCounter(&quot;SR-SF-0J-110-120&quot;); _counters[&quot;SR-SF-0J-120-140&quot;] = EventCounter(&quot;SR-SF-0J-120-140&quot;); _counters[&quot;SR-SF-0J-140-160&quot;] = EventCounter(&quot;SR-SF-0J-140-160&quot;); _counters[&quot;SR-SF-0J-160-180&quot;] = EventCounter(&quot;SR-SF-0J-160-180&quot;); _counters[&quot;SR-SF-0J-180-220&quot;] = EventCounter(&quot;SR-SF-0J-180-220&quot;); _counters[&quot;SR-SF-0J-220-260&quot;] = EventCounter(&quot;SR-SF-0J-220-260&quot;); _counters[&quot;SR-SF-0J-260&quot;] = EventCounter(&quot;SR-SF-0J-260&quot;); _counters[&quot;SR-SF-1J-100-105&quot;] = EventCounter(&quot;SR-SF-1J-100-105&quot;); _counters[&quot;SR-SF-1J-105-110&quot;] = EventCounter(&quot;SR-SF-1J-105-110&quot;); _counters[&quot;SR-SF-1J-110-120&quot;] = EventCounter(&quot;SR-SF-1J-110-120&quot;); _counters[&quot;SR-SF-1J-120-140&quot;] = EventCounter(&quot;SR-SF-1J-120-140&quot;); _counters[&quot;SR-SF-1J-140-160&quot;] = EventCounter(&quot;SR-SF-1J-140-160&quot;); _counters[&quot;SR-SF-1J-160-180&quot;] = EventCounter(&quot;SR-SF-1J-160-180&quot;); _counters[&quot;SR-SF-1J-180-220&quot;] = EventCounter(&quot;SR-SF-1J-180-220&quot;); _counters[&quot;SR-SF-1J-220-260&quot;] = EventCounter(&quot;SR-SF-1J-220-260&quot;); _counters[&quot;SR-SF-1J-260&quot;] = EventCounter(&quot;SR-SF-1J-260&quot;); set_analysis_name(&quot;ATLAS_13TeV_2OSLEP_chargino_139invfb&quot;); set_detector_name(detector); set_luminosity(139); set_bkgjson(&quot;ColliderBit/data/analyses_json_files/ATLAS_13TeV_2OSLEP_chargino_139invfb_bkgonly.json&quot;); } // The following section copied from Analysis_ATLAS_1LEPStop_20invfb.cpp void JetLeptonOverlapRemoval(vector&lt;const HEPUtils::Jet*&gt; &amp;jetvec, vector&lt;const HEPUtils::Particle*&gt; &amp;lepvec, double DeltaRMax) { //Routine to do jet-lepton check //Discards jets if they are within DeltaRMax of a lepton vector&lt;const HEPUtils::Jet*&gt; Survivors; for(unsigned int itjet = 0; itjet &lt; jetvec.size(); itjet++) { bool overlap = false; HEPUtils::P4 jetmom=jetvec.at(itjet)-&gt;mom(); for(unsigned int itlep = 0; itlep &lt; lepvec.size(); itlep++) { HEPUtils::P4 lepmom=lepvec.at(itlep)-&gt;mom(); double dR; dR=jetmom.deltaR_eta(lepmom); if(fabs(dR) &lt;= DeltaRMax) overlap=true; } if(overlap) continue; Survivors.push_back(jetvec.at(itjet)); } jetvec=Survivors; return; } void LeptonJetOverlapRemoval(vector&lt;const HEPUtils::Particle*&gt; &amp;lepvec, vector&lt;const HEPUtils::Jet*&gt; &amp;jetvec) { //Routine to do lepton-jet check //Discards leptons if they are within dR of a jet as defined in analysis paper vector&lt;const HEPUtils::Particle*&gt; Survivors; for(unsigned int itlep = 0; itlep &lt; lepvec.size(); itlep++) { bool overlap = false; HEPUtils::P4 lepmom=lepvec.at(itlep)-&gt;mom(); for(unsigned int itjet= 0; itjet &lt; jetvec.size(); itjet++) { HEPUtils::P4 jetmom=jetvec.at(itjet)-&gt;mom(); double dR; double DeltaRMax = std::min(0.4, 0.04 + 10 / lepmom.pT()); dR=jetmom.deltaR_eta(lepmom); if(fabs(dR) &lt;= DeltaRMax) overlap=true; } if(overlap) continue; Survivors.push_back(lepvec.at(itlep)); } lepvec=Survivors; return; } struct ptComparison { bool operator() (const HEPUtils::Particle* i,const HEPUtils::Particle* j) {return (i-&gt;pT()&gt;j-&gt;pT());} } comparePt; void run(const HEPUtils::Event* event) { _cutflow.fillinit(); // Baseline objects double met = event-&gt;met(); // Electrons vector&lt;const HEPUtils::Particle*&gt; electrons; for (const HEPUtils::Particle* electron : event-&gt;electrons()) { if (electron-&gt;pT() &gt; 10. &amp;&amp; fabs(electron-&gt;eta()) &lt; 2.47) electrons.push_back(electron); } // Apply electron efficiency applyEfficiency(electrons, ATLAS::eff2DEl.at(&quot;Generic&quot;)); // Muons vector&lt;const HEPUtils::Particle*&gt; muons; for (const HEPUtils::Particle* muon : event-&gt;muons()) { if (muon-&gt;pT() &gt; 10. &amp;&amp; fabs(muon-&gt;eta()) &lt; 2.7) muons.push_back(muon); } // Apply muon efficiency applyEfficiency(muons, ATLAS::eff2DMu.at(&quot;Generic&quot;)); // Jets vector&lt;const HEPUtils::Jet*&gt; candJets; for (const HEPUtils::Jet* jet : event-&gt;jets(&quot;antikt_R04&quot;)) { if (jet-&gt;pT() &gt; 20. &amp;&amp; fabs(jet-&gt;eta()) &lt; 2.4) candJets.push_back(jet); } // Scalar sum of the transverse momenta from all the reconstructed hard objects //double HT = 0.0; (Unused) //for (const HEPUtils::Jet* j : candJets) HT += j-&gt;pT(); (Unused) //for (const HEPUtils::Particle* e : electrons) HT += e-&gt;pT(); (Unused) //for (const HEPUtils::Particle* mu : muons) HT += mu-&gt;pT(); (Unused) // Overlap removal JetLeptonOverlapRemoval(candJets,electrons,0.2); LeptonJetOverlapRemoval(electrons,candJets); JetLeptonOverlapRemoval(candJets,muons,0.4); LeptonJetOverlapRemoval(muons,candJets); // Jets vector&lt;const HEPUtils::Jet*&gt; bJets; vector&lt;const HEPUtils::Jet*&gt; nonbJets; // Find b-jets // Copied from ATLAS_13TeV_3b_24invfb double btag = 0.85; double cmisstag = 1/12.; double misstag = 1./381.; for (const HEPUtils::Jet* jet : candJets) { // Tag if( jet-&gt;btag() &amp;&amp; random_bool(btag) ) bJets.push_back(jet); // Misstag c-jet else if( jet-&gt;ctag() &amp;&amp; random_bool(cmisstag) ) bJets.push_back(jet); // Misstag light jet else if( random_bool(misstag) ) bJets.push_back(jet); // Non b-jet else nonbJets.push_back(jet); } // Find signal leptons with pT &gt; 20 GeV vector&lt;const HEPUtils::Particle*&gt; signalElectrons; for (const HEPUtils::Particle* electron : electrons) { if (electron-&gt;pT() &gt; 25.) signalElectrons.push_back(electron); } vector&lt;const HEPUtils::Particle*&gt; signalMuons; for (const HEPUtils::Particle* muon : muons) { if (muon-&gt;pT() &gt; 25.) signalMuons.push_back(muon); } // Signal leptons = electrons + muons vector&lt;const HEPUtils::Particle*&gt; signalLeptons; signalLeptons=signalElectrons; signalLeptons.insert(signalLeptons.end(),signalMuons.begin(),signalMuons.end()); sort(signalLeptons.begin(),signalLeptons.end(),comparePt); // Tow exactly opposite-sign lepton