top_36invfb_nocovar // that don't make use of the covariance matrices class Analysis_CMS_13TeV_2LEPsoft_36invfb : public Analysis { protected: vector&lt;double&gt; cutFlowVector; vector&lt;string&gt; cutFlowVector_str; size_t NCUTS; vector&lt;double&gt; cutFlowVectorCMS_150_130; vector&lt;double&gt; cutFlowVectorCMS_150_143; vector&lt;double&gt; cutFlowVectorCMS_350_330; vector&lt;double&gt; cutFlowVectorCMS_350_340; // double xsecCMS_150_143; // double xsecCMS_150_130; // ofstream cutflowFile; public: // Required detector sim static constexpr const char* detector = &quot;CMS&quot;; struct ptComparison { bool operator() (const HEPUtils::Particle* i,const HEPUtils::Particle* j) {return (i-&gt;pT()&gt;j-&gt;pT());} } comparePt; Analysis_CMS_13TeV_2LEPsoft_36invfb() { // Counters for the number of accepted events for each signal region _counters[&quot;SREW1&quot;] = EventCounter(&quot;SREW1&quot;); _counters[&quot;SREW2&quot;] = EventCounter(&quot;SREW2&quot;); _counters[&quot;SREW3&quot;] = EventCounter(&quot;SREW3&quot;); _counters[&quot;SREW4&quot;] = EventCounter(&quot;SREW4&quot;); _counters[&quot;SREW5&quot;] = EventCounter(&quot;SREW5&quot;); _counters[&quot;SREW6&quot;] = EventCounter(&quot;SREW6&quot;); _counters[&quot;SREW7&quot;] = EventCounter(&quot;SREW7&quot;); _counters[&quot;SREW8&quot;] = EventCounter(&quot;SREW8&quot;); _counters[&quot;SREW9&quot;] = EventCounter(&quot;SREW9&quot;); _counters[&quot;SREW10&quot;] = EventCounter(&quot;SREW10&quot;); _counters[&quot;SREW11&quot;] = EventCounter(&quot;SREW11&quot;); _counters[&quot;SREW12&quot;] = EventCounter(&quot;SREW12&quot;); _counters[&quot;SRST1&quot;] = EventCounter(&quot;SRST1&quot;); _counters[&quot;SRST2&quot;] = EventCounter(&quot;SRST2&quot;); _counters[&quot;SRST3&quot;] = EventCounter(&quot;SRST3&quot;); _counters[&quot;SRST4&quot;] = EventCounter(&quot;SRST4&quot;); _counters[&quot;SRST5&quot;] = EventCounter(&quot;SRST5&quot;); _counters[&quot;SRST6&quot;] = EventCounter(&quot;SRST6&quot;