; // Set LocalHalo Model parameters to PICO-60 values Halo_primary_parameters-&gt;setValue(&quot;rho0&quot;, 0.3); Halo_primary_parameters-&gt;setValue(&quot;vrot&quot;, 220.); Halo_primary_parameters-&gt;setValue(&quot;v0&quot;, 220.); Halo_primary_parameters-&gt;setValue(&quot;vesc&quot;, 544.); ExtractLocalMaxwellianHalo.reset_and_calculate(); DDCalc_2_3_0_init.reset_and_calculate(); PICO_60_2019_Calc.reset_and_calculate(); PICO_60_2019_GetLogLikelihood.reset_and_calculate(); lnL4 = PICO_60_2019_GetLogLikelihood(0); #ifdef DARKBIT_STANDALONE_WIMP_DEBUG std::cout &lt;&lt; &quot;LZ_2022 SI lnL = &quot; &lt;&lt; lnL1 &lt;&lt; std::endl; std::cout &lt;&lt; &quot;PandaX_4T SI lnL = &quot; &lt;&lt; lnL2 &lt;&lt; std::endl; std::cout &lt;&lt; &quot;XENON1T_2018 SI lnL = &quot; &lt;&lt; lnL3 &lt;&lt; std::endl; std::cout &lt;&lt; &quot;PICO_60_2019 SI lnL = &quot; &lt;&lt; lnL4 &lt;&lt; std::endl; #endif DDCalc_2_3_0_init.reset_and_calculate(); LZ_2022_Calc.reset_and_calculate(); std::vector&lt;double&gt; events; LZ_2022_GetBinSignal.reset_and_calculate(); events = LZ_2022_GetBinSignal(0); #ifdef DARKBIT_STANDALONE_WIMP_DEBUG int nbins = events.size(); std::cout &lt;&lt; &quot;Number of LZ bins: &quot; &lt;&lt; nbins &lt;&lt; std::endl; std::cout &lt;&lt; &quot;Predicted signal: &quot;; for (auto x : events) std::cout &lt;&lt; x &lt;&lt; &quot; &quot;; std::cout &lt;&lt; std::endl; #endif lnL_array1[i][j] = lnL1; lnL_array2[i][j] = lnL2; lnL_array3[i][j] = lnL3; lnL_array4[i][j] = lnL4; } } dump_array_to_file(&quot;LZ_2022_SI_table.dat&quot;, lnL_array1, m_list, s_list); dump_array_to_file(&quot;PandaX_4T_SI_table.dat&quot;, lnL_array2, m_list, s_list); dump_array_to_file(&quot;XENON1T_2018_SI_table.dat&quot;, lnL_array3, m_list, s_list); dump_array_to_file(&quot;PICO_60_2019_SI_table.dat&quot;, lnL_array4, m_list, s_list); s_list = daFunk::logspace(-42., -35., sBins); // Calculate array of sigma_SI and lnL values for LZ, PandaX, XENON1T and PICO-60 // assuming gna=0 (proton-only) std::cout &lt;&lt; &quot;Calculating tables of SD likelihoods.&quot; &lt;&lt; std::endl; for (size_t i = 0; i &lt; m_list.size(); i++) { for (size_t j = 0; j &lt; s_list.size(); j++) { // Re-initialize DDCalc with LZ/Xenon/PandaX halo parameters Halo_primary_parameters-&gt;setValue(&quot;rho0&quot;, 0.3); Halo_primary_parameters-&gt;setValue(&quot;vrot&quot;, 232.7); // v_Earth = 245 km/s Halo_primary_parameters-&gt;setValue(&quot;v0&quot;, 220.); Halo_primary_parameters-&gt;setValue(&quot;vesc&quot;, 544.); ExtractLocalMaxwellianHalo.reset_and_calculate(); DarkMatter_ID_WIMP.reset_and_calculate(); DarkMatterConj_ID_WIMP.reset_and_calculate(); WIMP_properties_WIMP.setOption&lt;double&gt;(&quot;mWIMP&quot;, m_list[i]); WIMP_properties_WIMP.reset_and_calculate(); mwimp_generic.reset_and_calculate(); #ifdef DARKBIT_STANDALONE_WIMP_DEBUG std::cout &lt;&lt; &quot;Parameters: &quot; &lt;&lt; m_list[i] &lt;&lt; &quot; &quot; &lt;&lt; s_list[j] &lt;&lt; std::endl; #endif reduced_mass = (m_list[i] * m_proton) / (m_proton + m_list[i]); g = sqrt(s_list[j]*pi/(3*gev2cm2)) / (reduced_mass); TH_ProcessCatalog_WIMP.reset_and_calculate(); RD_fraction_one.reset_and_calculate(); DD_couplings_WIMP.setOption&lt;double&gt;(&quot;gps&quot;, 0.); DD_couplings_WIMP.setOption&lt;double&gt;(&quot;gns&quot;, 0.); DD_couplings_WIMP.setOption&lt;double&gt;(&quot;gpa&quot;, g); DD_couplings_WIMP.setOption&lt;double&gt;(&quot;gna&quot;, 0.); DD_couplings_WIMP.reset_and_calculate(); DDCalc_2_3_0_init.reset_and_calculate(); LZ_2022_Calc.reset_and_calculate(); LZ_2022_GetLogLikelihood.reset_and_calculate(); XENON1T_2018_Calc.reset_and_calculate(); XENON1T_2018_GetLogLikelihood.reset_and_calculate(); PandaX_4T_Calc.reset_and_calculate(); PandaX_4T_GetLogLikelihood.reset_and_calculate(); lnL1 = LZ_2022_GetLogLikelihood(0); lnL2 = PandaX_4T_GetLogLikelihood(0); lnL3 = XENON1T_2018_GetLogLikelihood(0); // Set LocalHalo Model parameters to PICO-60 values Halo_primary_parameters-&gt;setValue(&quot;rho0&quot;, 0.3); Halo_primary_parameters-&gt;setValue(&quot;vrot&quot;, 220.); Halo_primary_parameters-&gt;setValue(&quot;v0&quot;, 220.); Halo_primary_parameters-&gt;setValue(&quot;vesc&quot;, 544.); ExtractLocalMaxwellianHalo.reset_and_calculate(); DDCalc_2_3_0_init.reset_and_calculate(); PICO_60_2019_Calc.reset_and_calculate(); PICO_60_2019_GetLogLikelihood.reset_and_calculate(); lnL4 = PICO_60_2019_GetLogLikelihood(0); #ifdef DARKBIT_STANDALONE_WIMP_DEBUG std::cout &lt;&lt; &quot;LZ_2022 SD lnL = &quot; &lt;&lt; lnL1 &lt;&lt; std::endl; std::cout &lt;&lt; &quot;PandaX_4T SD lnL = &quot; &lt;&lt; lnL2 &lt;&lt; std::endl; std::cout &lt;&lt; &quot;XENON1T_2018 SD lnL = &quot; &lt;&lt; lnL3 &lt;&lt; std::endl; std::cout &lt;&lt; &quot;PICO_60_2019 SD lnL = &quot; &lt;&lt; lnL4 &lt;&lt; std::endl; #endif lnL_array1[i][j] = lnL1; lnL_array2[i][j] = lnL2; lnL_array3[i][j] = lnL3; lnL_array4[i][j] = lnL4; } } dump_array_to_file(&quot;LZ_2022_SD_table.dat&quot;, lnL_array1, m_list, s_list); dump_array_to_file(&quot;PandaX_4T_SD_table.dat&quot;, lnL_array2, m_list, s_list); dump_array_to_file(&quot;XENON1T_2018_SD_table.dat&quot;, lnL_array3, m_list, s_list); dump_array_to_file(&quot;PICO_60_2019_SD_table.dat&quot;, lnL_array4, m_list, s_list); // Reset halo parameters to DarkBit defaults. Halo_primary_parameters-&gt;setValue(&quot;rho0&quot;, 0.4); Halo_primary_parameters-&gt;setValue(&quot;vrot&quot;, 235.); Halo_primary_parameters-&gt;setValue(&quot;v0&quot;, 235.); Halo_primary_parameters-&gt;setValue(&quot;vesc&quot;, 550.); ExtractLocalMaxwellianHalo.reset_and_calculate(); GalacticHalo_Einasto.reset_and_calculate(); } // AMS-02 antiproton likelihoods for annihilation into b bbar if (mode==8) { std::cout &lt;&lt; &quot;\\nCalculating antiproton likelihoods for annihilation to b bbar.&quot; &lt;&lt; std::endl; DarkMatter_ID_WIMP.reset_and_calculate(); WIMP_properties_WIMP.setOption&lt;double&gt;(&quot;mWIMP&quot;, 100.0); WIMP_properties_WIMP.reset_and_calculate(); mwimp_generic.reset_and_calculate(); TH_ProcessCatalog_WIMP.setOption&lt;double&gt;(&quot;sv&quot;, 3e-26); TH_ProcessCatalog_WIMP.setOption&lt;std::vector&lt;double&gt;&gt;(&quot;brList&quot;, daFunk::vec&lt;double&gt;(1., 0., 0., 0., 0., 0., 0., 0.)); TH_ProcessCatalog_WIMP.reset_and_calculate(); pbarlike_1_0_init.setOption&lt;std::string&gt;(&quot;PropagationModel&quot;,&quot;INJ.BRK&quot;); pbarlike_1_0_init.setOption&lt;bool&gt;(&quot;PreventExtrapolation&quot;,true); pbarlike_1_0_init.setOption&lt;std::vector&lt;std::vector&lt;double&gt;&gt;&gt;(&quot;PropagationParameters&quot;, std::vector&lt;std::vector&lt;double&gt;&gt;((0.0))); std::cout&lt;&lt; &quot;\\nParameters: 100 GeV, 3e-26 cm3s-1; Propagation Model: Injection break (INJ.BRK)&quot; &lt;&lt; std::endl; pbarlike_1_0_init.reset_and_calculate(); lnL_pbarAMS02.reset_and_calculate(); map_str_dbl lnL = lnL_pbarAMS02(0); std::cout&lt;&lt; &quot;\\nLog-likelihood ratio (using uncorrelated errors): &quot; &lt;&lt; lnL[&quot;uncorrelated&quot;] &lt;&lt; std::endl; std::cout&lt;&lt; &quot;Log-likelihood ratio (using correlated errors): &quot; &lt;&lt; lnL[&quot;correlated&quot;] &lt;&lt; std::endl; } } catch (std::exception&amp; e) { std::cout &lt;&lt; &quot;DarkBit_standalone_WIMP has exited with fatal exception: &quot; &lt;&lt; e.what() &lt;&lt; std::endl; } return 0; } Updated on 2026-11-03 at 14:50:46 +0000
