del_SLHA2_hpp__ // Standard Model parameterisation in SLHA2 conventions #define MODEL StandardModel_SLHA2 START_MODEL DEFINEPARS(alphainv, GF, alphaS) // 1,2,3 DEFINEPARS(mZ) // 4 DEFINEPARS(mE, mMu, mTau) // 11,13,7 DEFINEPARS(mNu1, mNu2, mNu3) // 12,14,8 DEFINEPARS(mD, mU) // 21,22 DEFINEPARS(mS, mCmC) // 23,24 DEFINEPARS(mBmB, mT) // 5,6 // CKM parameters DEFINEPARS(CKM_lambda, CKM_A, CKM_rhobar, CKM_etabar) // PMNS parameters DEFINEPARS(theta12, theta23, theta13) DEFINEPARS(delta13, alpha1, alpha2) #undef MODEL #endif Updated on 2026-11-03 at 14:50:46 +0000
